import{_ as a,o as t,c as s,a3 as o}from"./chunks/framework.DhF4LrUq.js";const n="/shipperdog/snapshot/screenshots/console-login.png",r="/shipperdog/snapshot/screenshots/console-dashboard.png",i="/shipperdog/snapshot/screenshots/console-tenants.png",l="/shipperdog/snapshot/screenshots/console-applications.png",h="/shipperdog/snapshot/screenshots/console-application-banking.png",p="/shipperdog/snapshot/screenshots/console-releases.png",d="/shipperdog/snapshot/screenshots/console-release-detail.png",c="/shipperdog/snapshot/screenshots/console-rings.png",g="/shipperdog/snapshot/screenshots/console-approval-workflows.png",u="/shipperdog/snapshot/screenshots/portal-home.png",m="/shipperdog/snapshot/screenshots/portal-history.png",P=JSON.parse('{"title":"Platform tour","description":"A guided walk-through of the ShipperDog Console and Tester Portal — every screen a release team touches, with real screenshots.","frontmatter":{"description":"A guided walk-through of the ShipperDog Console and Tester Portal — every screen a release team touches, with real screenshots."},"headers":[],"relativePath":"get-started/platform-tour.md","filePath":"get-started/platform-tour.md"}'),f={name:"get-started/platform-tour.md"};function w(v,e,b,y,T,k){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="platform-tour" tabindex="-1">Platform tour <a class="header-anchor" href="#platform-tour" aria-label="Permalink to &quot;Platform tour&quot;">​</a></h1><p>This walk-through visits every screen a release team touches, in the order work usually flows. The screenshots come from the locally running development stack with its seeded demo world (an organization with two tenants, Acme and Contoso, and a Banking application) — what you see here is what you will see there.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><p>The Console opens on the login page. Organization members sign in with email and password, or — when your organization has single sign-on configured — enter the organization id and continue through your corporate provider. Sign-in failures are deliberately unhelpful: the same message for a wrong password, an unknown account, or a locked one.</p><p><img src="'+n+'" alt="The Console login page"></p><h2 id="the-organization-dashboard" tabindex="-1">The organization dashboard <a class="header-anchor" href="#the-organization-dashboard" aria-label="Permalink to &quot;The organization dashboard&quot;">​</a></h2><p>After signing in you land on the organization dashboard: the six counts (applications, tenants, active releases, pending approvals, testing, production), a release-health row per application, and — the part worth leaving open on a second monitor — the pending-actions panel: the approval steps waiting on <em>you</em>, the security-review queue, and the failed gates you have authority to override, each deep-linking straight to the release it acts on. The view refreshes every 30 seconds.</p><p><img src="'+r+'" alt="The organization dashboard"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The navigation only shows the sections your role can use — each item probes the API before it renders. The backend enforces every call regardless; the navigation decides what renders, never what is allowed.</p></div><h2 id="tenants" tabindex="-1">Tenants <a class="header-anchor" href="#tenants" aria-label="Permalink to &quot;Tenants&quot;">​</a></h2><p>Tenants are the customer or business entities releases target. The listing carries the search and status filters, and each row opens member management (the roster with roles and membership status), device management, and the tenant dashboard. Creation and lifecycle changes are organization-administrator territory.</p><p><img src="'+i+'" alt="The tenants listing"></p><h2 id="applications" tabindex="-1">Applications <a class="header-anchor" href="#applications" aria-label="Permalink to &quot;Applications&quot;">​</a></h2><p>The application registry has two views of the same data: all applications (the organization-wide administration view, including shared applications before their first tenant authorization) and by tenant (a tenant&#39;s effective visibility — owned plus authorized shared). Registering an application pins its bundle id and package name, which the artifact pipeline later verifies every build against.</p><p><img src="'+l+'" alt="The applications registry"></p><p>Opening an application shows its metadata, ownership scope, and — for shared applications — the authorized-tenants screen where visibility is granted and revoked with reasons.</p><p><img src="'+h+'" alt="The Banking application detail"></p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;Releases&quot;">​</a></h2><p>The release listing is application-addressed: pick the application (and tenant, if you like), and the releases appear newest first with status chips from the lifecycle vocabulary. Filters ride the server; ring and release-ref search filter the loaded pages.</p><p><img src="'+p+'" alt="The Banking releases listing"></p><h2 id="the-release-dashboard" tabindex="-1">The release dashboard <a class="header-anchor" href="#the-release-dashboard" aria-label="Permalink to &quot;The release dashboard&quot;">​</a></h2><p>One screen per release — the surface a Release Manager lives in:</p><ul><li><strong>Lifecycle actions</strong> offering exactly the legal edges of the state machine (failure and rollback open a mandatory-reason dialog);</li><li><strong>Artifacts</strong>, flipping from the creation slots to the frozen content pins once the manifest exists;</li><li><strong>Approvals</strong> rendering the live round: group modes, the waiting-on list, recorded signatures, and the approve/reject affordances on exactly the decidable steps;</li><li><strong>Quality gates</strong> with per-gate states, evidence links, observed values against thresholds, and the audited override;</li><li><strong>Distribution</strong> (starting ring, environment, resolved targets) and the <strong>promotion</strong> engine: the promote action, the &quot;why can&#39;t I promote&quot; precheck, and the append-only promotions timeline;</li><li>The <strong>state timeline</strong> and the <strong>frozen manifest</strong> with its digest, YAML compliance render, and diff against another approved release.</li></ul><p>The screenshot shows a release waiting in <code>APPROVAL_PENDING</code>: QA has signed, Security and the Release Manager are the waiting-on list, and both required gates passed with evidence links.</p><p><img src="'+d+'" alt="The release dashboard"></p><h2 id="rings-and-approval-workflows" tabindex="-1">Rings and approval workflows <a class="header-anchor" href="#rings-and-approval-workflows" aria-label="Permalink to &quot;Rings and approval workflows&quot;">​</a></h2><p>Two organization-level screens shape how releases move:</p><ul><li><p><strong>Release rings</strong> — the rollout ladder. The seeded five (Engineering, QA, Tenant Pilot, UAT, Production — always last), plus your custom rings, each carrying its eligibility rules, approval-policy reference, promotion policy, and gate set.</p><p><img src="'+c+'" alt="The rings editor"></p></li><li><p><strong>Approval workflows</strong> — the definitions editor: ordered groups of steps (ALL / ANY modes, conditional steps, tenant scopes) over the five approval roles. The definition attached to a ring is the chain that release&#39;s approvals run (or, when the targeted environment binds a policy name, that chain instead).</p><p><img src="'+g+'" alt="The approval workflows editor"></p></li></ul><h2 id="the-tester-portal-phone" tabindex="-1">The Tester Portal (phone) <a class="header-anchor" href="#the-tester-portal-phone" aria-label="Permalink to &quot;The Tester Portal (phone)&quot;">​</a></h2><p>Testers live in a separate app on their phones. After signing in, the home screen is <strong>My Applications</strong> — one card per application the server says they can install, with the latest authorized version and per-platform availability. Tapping a card opens the version history with download buttons per platform.</p><p><img src="'+u+'" alt="The Tester Portal on a phone"></p><p><img src="'+m+'" alt="The portal version history"></p><p>Downloads ask the authorization engine first; an allow returns a short-lived signed URL with platform-appropriate install guidance — and for builds embedding the telemetry SDK, the token that pairs the install with its release. <strong>Report issue</strong> on any version opens the feedback form with the device context attached automatically. The whole tester story is its own guide: <a href="/shipperdog/snapshot/get-started/five-minute-install">five-minute install</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/get-started/concepts">Core concepts</a> if you skipped it</li><li>The role guides (in the Roles section) for persona-specific paths</li><li><a href="/shipperdog/snapshot/concepts/release-lifecycle">Release lifecycle</a>, <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a>, and <a href="/shipperdog/snapshot/concepts/rings-and-rollout">rings and rollout</a> for the models behind these screens</li></ul>',35)])])}const q=a(f,[["render",w]]);export{P as __pageData,q as default};
